text:
{
  "design": {
    "theme": "crayon",
    "picture_style": "illustration"
  },
  "flow": [
    {
      "slide": 1,
      "does": "Recall fair sharing",
      "look_at": {"kind": "none", "shows": null},
      "teaches": []
    },
    {
      "slide": 2,
      "does": "Introduce the learning objectives",
      "look_at": {"kind": "none", "shows": null},
      "teaches": []
    },
    {
      "slide": 3,
      "does": "Teach halves and quarters of shapes",
      "look_at": {"kind": "diagram", "shows": "Equal wholes split into two and four equal parts"},
      "teaches": [1]
    },
    {
      "slide": 4,
      "does": "Identify shaded fractions",
      "look_at": {"kind": "diagram", "shows": "Two shapes with one part shaded"},
      "teaches": [1]
    },
    {
      "slide": 5,
      "does": "Correct the unequal-parts misconception",
      "look_at": {"kind": "diagram", "shows": "A whole split into parts of different sizes"},
      "teaches": [1]
    },
    {
      "slide": 6,
      "does": "Check what makes a quarter",
      "look_at": {"kind": "none", "shows": null},
      "teaches": [1]
    },
    {
      "slide": 7,
      "does": "Model finding half of ten",
      "look_at": {"kind": "diagram", "shows": "Ten counters shared into two equal groups"},
      "teaches": [2]
    },
    {
      "slide": 8,
      "does": "Find half of twelve",
      "look_at": {"kind": "diagram", "shows": "Twelve counters ready to be shared"},
      "teaches": [2]
    },
    {
      "slide": 9,
      "does": "Model finding a quarter of twelve",
      "look_at": {"kind": "diagram", "shows": "Twelve counters shared into four equal groups"},
      "teaches": [3]
    },
    {
      "slide": 10,
      "does": "Find a quarter of sixteen",
      "look_at": {"kind": "diagram", "shows": "Sixteen counters ready to be shared"},
      "teaches": [3]
    },
    {
      "slide": 11,
      "does": "Apply sharing to new amounts",
      "look_at": {"kind": "none", "shows": null},
      "teaches": [2, 3]
    },
    {
      "slide": 12,
      "does": "Apply fractions in a new setting, then complete the worksheet exit ticket",
      "look_at": {"kind": "none", "shows": null},
      "teaches": [1, 2, 3]
    }
  ],
  "title": {
    "template": "title",
    "heading": "Halves and quarters",
    "lead": "Share 4 apples fairly between 2 children. How many each?",
    "picture": null
  },
  "slides": [
    {
      "template": "visual-text",
      "heading": "Equal parts",
      "lead": "Equal parts are the same size.",
      "points": [
        "One half: one of two equal parts.",
        "One quarter: one of four equal parts."
      ],
      "figure": {
        "kind": "fraction-shapes",
        "shows": "Two identical rectangles show one half and one quarter shaded.",
        "alt": "The first rectangle has one of two equal parts shaded. The second has one of four equal parts shaded.",
        "title": null,
        "shapes": [
          {"shape": "rectangle", "parts": 2, "cut": "vertical", "shaded": 1, "name": "½"},
          {"shape": "rectangle", "parts": 4, "cut": "vertical", "shaded": 1, "name": "¼"}
        ]
      }
    },
    {
      "template": "big-visual",
      "heading": "Name the shaded part",
      "lead": "Say half or quarter for A and B. Explain why.",
      "figure": {
        "kind": "fraction-shapes",
        "shows": "Two shapes for pupils to identify by counting equal parts.",
        "alt": "Shape A is a square with four equal parts and one shaded. Shape B is a circle with two equal parts and one shaded.",
        "title": null,
        "shapes": [
          {"shape": "square", "parts": 4, "cut": "grid", "shaded": 1, "name": "A"},
          {"shape": "circle", "parts": 2, "cut": "auto", "shaded": 1, "name": "B"}
        ]
      }
    },
    {
      "template": "visual-text",
      "heading": "Two parts: always halves?",
      "lead": "These are two parts, but they are not halves.",
      "points": [
        {"label": "Equal", "text": "Halves must be the same size."}
      ],
      "figure": {
        "kind": "bar-model",
        "shows": "One bar split into unequal lengths, with the shorter part shaded.",
        "alt": "A bar is split into a short shaded part and a part three times as long.",
        "title": null,
        "bars": [
          {
            "label": null,
            "whole": null,
            "parts": null,
            "values": [1, 3],
            "shaded": 1,
            "unknown": "none",
            "unit": null
          }
        ],
        "combined": false
      }
    },
    {
      "template": "hinge",
      "heading": "Choose one answer",
      "stem": "Which tells us about one quarter?",
      "options": [
        "One of four equal parts",
        "One of four parts of any size",
        "One of two equal parts"
      ],
      "correct": 1
    },
    {
      "template": "steps",
      "heading": "Find half of 10",
      "points": [
        "Count 10 counters.",
        "Share into 2 equal groups.",
        "Count one group: half of 10 is 5."
      ],
      "figure": {
        "kind": "equal-groups",
        "shows": "Ten counters shared fairly between two groups.",
        "alt": "Two rings each contain five counters.",
        "title": null,
        "total": 10,
        "groups": 2,
        "layout": "rings",
        "show_count": "each",
        "unknown": false
      }
    },
    {
      "template": "big-visual",
      "heading": "Find half of 12",
      "lead": "Draw 2 rings. Share these counters equally. Count one group.",
      "figure": {
        "kind": "equal-groups",
        "shows": "An unshared collection of twelve counters for pupils to redraw in two groups.",
        "alt": "Twelve counters are shown in one row, not yet shared.",
        "title": null,
        "total": 12,
        "groups": 10,
        "layout": "rows",
        "show_count": "none",
        "unknown": false
      }
    },
    {
      "template": "steps",
      "heading": "Find a quarter of 12",
      "points": [
        "Count 12 counters.",
        "Share into 4 equal groups.",
        "Count one group: a quarter of 12 is 3."
      ],
      "figure": {
        "kind": "equal-groups",
        "shows": "Twelve counters shared fairly between four groups.",
        "alt": "Four rings each contain three counters.",
        "title": null,
        "total": 12,
        "groups": 4,
        "layout": "rings",
        "show_count": "each",
        "unknown": false
      }
    },
    {
      "template": "big-visual",
      "heading": "Find a quarter of 16",
      "lead": "Draw 4 rings. Share these counters equally. Count one group.",
      "figure": {
        "kind": "equal-groups",
        "shows": "An unshared collection of sixteen counters for pupils to redraw in four groups.",
        "alt": "Sixteen counters are shown in one row, not yet shared.",
        "title": null,
        "total": 16,
        "groups": 10,
        "layout": "rows",
        "show_count": "none",
        "unknown": false
      }
    },
    {
      "template": "practice",
      "heading": "Draw and share",
      "questions": [
        "Find half of 18 counters.",
        "Find a quarter of 8 counters.",
        "Stretch: find half and a quarter of 20. Compare."
      ],
      "instruction": "Draw equal groups. Circle the group you count.",
      "picture": null
    },
    {
      "template": "practice",
      "heading": "Plan a picnic",
      "questions": [
        "Draw a square sandwich. Show one quarter.",
        "There are 14 grapes. Find half of them.",
        "There are 20 berries. Find a quarter of them."
      ],
      "instruction": "Draw your answers on the worksheet.",
      "picture": null
    }
  ]
}
